# Spec 131: are the 68 TFs selected as higher in mesothelioma tumours more required for viability than the other TFs with chromVAR activity? DepMap 24Q4 CRISPR gene effect, all 21 mesothelioma lines.
#   selected   = scatac_ArchR/selected_TF.rds (68 TFs)
#   background = the other TFs with a chromVAR motif deviation matched to a gene (scatac_ArchR/TF_activators_genescore.rds, GeneScoreMatrix_name; 764 TFs in total)
# per TF: median Chronos gene effect over the 21 mesothelioma lines (< 0 = loss of fitness), number of lines with dependency probability > 0.5, mesothelioma selectivity (median in mesothelioma - median in all other lines)
#   A  distribution of the median gene effect, selected vs background (Wilcoxon), and shares of TFs that are a dependency in >= 1 line / >= half of the lines (Fisher)
#   B  the same contrast in every single mesothelioma line (median of the selected minus median of the background, Wilcoxon p)
#   C  the 68 TFs ranked, with the number of dependent lines
#   D  adjusted for expression: gene effect vs expression in mesothelioma lines (CCLE log2 TPM, pleura lines); lm(effect ~ selected + expression)
#   E  mesothelioma selectivity, selected vs background
# needs: DepMap 24Q4 (DEPMAP_DIR), ARCHR_DIR, CCLE_RNAseq_rsem_genes_tpm.rds
# outputs: spec131_TF_depmap_meso.csv, spec131_tests.csv, spec131_per_line.csv, fig47_depmap_selected_TFs.{png,pdf}
here <- dirname(normalizePath(sub("^--file=", "", grep("^--file=", commandArgs(FALSE), value = TRUE)[1])))
source(file.path(here, "repro_common.R")); source(file.path(here, "profiles.R")); source(file.path(here, "agree_common.R")); options(width = 220)
DM <- Sys.getenv("DEPMAP_DIR", unset = "/sc/arion/projects/Tsankov_Normal_Lung/Bruno/Public_data/DepMap_24Q4"); AR <- Sys.getenv("ARCHR_DIR", unset = "/sc/arion/projects/Tsankov_Normal_Lung/Bruno/mesothelioma/scATAC_PM/tumor_compartment/scatac_ArchR")
CCLE <- "/sc/arion/projects/Tsankov_Normal_Lung/Bruno/Public_data/CCLE/CCLE_RNAseq_rsem_genes_tpm.rds"; fp <- function(p) ifelse(is.na(p), "n/a", ifelse(p < 0.001, formatC(p, format = "e", digits = 1), formatC(p, format = "g", digits = 2)))
sel <- readRDS(file.path(AR, "selected_TF.rds")); suppressPackageStartupMessages(library(S4Vectors)); allTF <- unique(as.character(readRDS(file.path(AR, "TF_activators_genescore.rds"))$GeneScoreMatrix_name)); allTF <- union(allTF, sel)
hd <- strsplit(readLines(file.path(DM, "CRISPRGeneEffect.csv"), n = 1), ",")[[1]]; sym <- sub(" \\(.*", "", hd); tf <- intersect(allTF, sym); rdm <- function(f) { x <- data.table::fread(file.path(DM, f), select = c(1, match(tf, sym)), data.table = FALSE); M <- as.matrix(x[, -1]); dimnames(M) <- list(x[[1]], tf); M }
GE <- rdm("CRISPRGeneEffect.csv"); GD <- rdm("CRISPRGeneDependency.csv"); mo <- read.csv(file.path(DM, "Model.csv"), stringsAsFactors = FALSE); mo <- mo[mo$ModelID %in% rownames(GE), ]; ms <- mo[grepl("esotheli", paste(mo$OncotreePrimaryDisease, mo$OncotreeSubtype)), ]
E <- GE[ms$ModelID, ]; rownames(E) <- ms$StrippedCellLineName; Pd <- GD[ms$ModelID, ]; oth <- setdiff(rownames(GE), ms$ModelID)
cat("TFs with chromVAR activity:", length(allTF), "| in DepMap:", length(tf), "| selected:", length(sel), "of which in DepMap:", sum(sel %in% tf), "| missing:", setdiff(sel, tf), "| mesothelioma lines:", nrow(E), "\n")
X <- readRDS(CCLE); pl <- grep("_PLEURA$", colnames(X), value = TRUE); ex <- setNames(apply(log2(as.matrix(X[intersect(tf, rownames(X)), pl]) + 1), 1, median), intersect(tf, rownames(X)))
T <- data.frame(TF = tf, selected = tf %in% sel, meso_median = apply(E, 2, median, na.rm = TRUE), meso_mean = colMeans(E, na.rm = TRUE), meso_min = apply(E, 2, min, na.rm = TRUE), n_dependent = colSums(Pd > 0.5, na.rm = TRUE), other_median = apply(GE[oth, ], 2, median, na.rm = TRUE), expr_meso = ex[tf], stringsAsFactors = FALSE)
T$selectivity <- T$meso_median - T$other_median; T$p_meso_vs_other <- sapply(tf, function(k) wilcox.test(E[, k], GE[oth, k])$p.value); T <- T[order(T$meso_median), ]; write.csv(T, file.path(OUT, "spec131_TF_depmap_meso.csv"), row.names = FALSE); a <- T[T$selected, ]; b <- T[!T$selected, ]
ft <- function(x, y) fisher.test(matrix(c(sum(x), sum(!x), sum(y), sum(!y)), 2)); w1 <- wilcox.test(a$meso_median, b$meso_median); f1 <- ft(a$n_dependent >= 1, b$n_dependent >= 1); f2 <- ft(a$n_dependent >= 11, b$n_dependent >= 11); f3 <- ft(a$meso_median < -0.25, b$meso_median < -0.25)
m1 <- summary(lm(meso_median ~ selected + expr_meso, T))$coef; w2 <- wilcox.test(a$selectivity, b$selectivity); wx <- wilcox.test(a$expr_meso, b$expr_meso)
set.seed(1); bins <- cut(T$expr_meso, quantile(T$expr_meso, 0:5 / 5, na.rm = TRUE), include.lowest = TRUE); obs <- mean(a$meso_median); nulm <- replicate(10000, { s <- unlist(lapply(levels(bins), function(l) sample(which(bins == l & !T$selected), min(sum(bins == l & T$selected, na.rm = TRUE), sum(bins == l & !T$selected, na.rm = TRUE))))); mean(T$meso_median[s]) }); p_match <- mean(nulm <= obs)
TS <- data.frame(test = c("median gene effect, selected vs background (Wilcoxon)", "dependency in >= 1 line (Fisher)", "dependency in >= 11 of 21 lines (Fisher)", "median gene effect < -0.25 (Fisher)", "selected, adjusted for expression (lm coefficient)", "expression-matched background (10,000 draws, mean effect)", "mesothelioma selectivity, selected vs background (Wilcoxon)", "expression in mesothelioma lines, selected vs background (Wilcoxon)"),
                 selected = c(median(a$meso_median), mean(a$n_dependent >= 1), mean(a$n_dependent >= 11), mean(a$meso_median < -0.25), m1["selectedTRUE", 1], obs, median(a$selectivity), median(a$expr_meso, na.rm = TRUE)), background = c(median(b$meso_median), mean(b$n_dependent >= 1), mean(b$n_dependent >= 11), mean(b$meso_median < -0.25), NA, mean(nulm), median(b$selectivity), median(b$expr_meso, na.rm = TRUE)),
                 p = c(w1$p.value, f1$p.value, f2$p.value, f3$p.value, m1["selectedTRUE", 4], p_match, w2$p.value, wx$p.value)); write.csv(TS, file.path(OUT, "spec131_tests.csv"), row.names = FALSE); print(TS, digits = 3, row.names = FALSE)
PL <- do.call(rbind, lapply(rownames(E), function(l) { v <- E[l, ]; s <- names(v) %in% sel; data.frame(line = l, selected_median = median(v[s], na.rm = TRUE), background_median = median(v[!s], na.rm = TRUE), diff = median(v[s], na.rm = TRUE) - median(v[!s], na.rm = TRUE), p = wilcox.test(v[s], v[!s])$p.value, n_dep_selected = sum(Pd[ms$ModelID[ms$StrippedCellLineName == l], s] > 0.5, na.rm = TRUE)) }))
PL <- PL[order(PL$diff), ]; write.csv(PL, file.path(OUT, "spec131_per_line.csv"), row.names = FALSE); cat(sprintf("\nper line: selected lower than background in %d of %d lines; p < 0.05 in %d\n", sum(PL$diff < 0), nrow(PL), sum(PL$p < 0.05 & PL$diff < 0)))
cat("\nselected TFs that are dependencies (>= 5 lines):\n"); print(a[a$n_dependent >= 5, c("TF", "meso_median", "n_dependent", "other_median", "selectivity", "p_meso_vs_other", "expr_meso")], digits = 2, row.names = FALSE)
cat("\nmost mesothelioma-selective among the selected (selectivity < -0.1 and p < 0.05):\n"); print(a[a$selectivity < -0.1 & a$p_meso_vs_other < 0.05, c("TF", "meso_median", "other_median", "selectivity", "p_meso_vs_other", "n_dependent")], digits = 2, row.names = FALSE)
cat("\nbackground TFs with the strongest effects (for reference):", paste(head(b$TF, 15), collapse = " "), "\n")

SC <- "#eb6834"; BC <- "grey60"
save_fig("fig47_depmap_selected_TFs", 17, 11, function() {
  layout(rbind(c(1, 2, 3, 3), c(4, 5, 3, 3)), widths = c(1, 1, 0.8, 0.8)); par(oma = c(0, 0, 3.6, 0.4), family = "sans"); ttl <- function(x, y) { mtext(x, side = 3, adj = 0, line = 1.5, font = 2, cex = 0.8); mtext(y, side = 3, adj = 0, line = 0.4, cex = 0.56, col = INK2) }
  par(mar = c(4.4, 4.8, 3.4, 1)); plot(ecdf(b$meso_median), col = BC, lwd = 2, main = "", xlab = "median gene effect over the 21 mesothelioma lines", ylab = "cumulative share of TFs", las = 1, bty = "n", cex.axis = 0.8, do.points = FALSE, verticals = TRUE, xlim = c(-1.6, 0.4)); plot(ecdf(a$meso_median), col = SC, lwd = 2.4, add = TRUE, do.points = FALSE, verticals = TRUE)
  abline(v = c(0, -0.5, -1), lty = c(1, 3, 2), col = c(INK, MUTED, MUTED)); legend("topleft", c(sprintf("68 selected TFs (%d in DepMap): median %.2f", nrow(a), median(a$meso_median)), sprintf("other chromVAR TFs (%d): median %.2f", nrow(b), median(b$meso_median))), col = c(SC, BC), lwd = 2.4, bty = "n", cex = 0.66)
  ttl("A  viability effect, selected vs other TFs", sprintf("Wilcoxon p %s; dependency in >= 1 line: %.0f%% vs %.0f%% (p %s); in >= 11 lines: %.0f%% vs %.0f%% (p %s)", fp(w1$p.value), 100 * mean(a$n_dependent >= 1), 100 * mean(b$n_dependent >= 1), fp(f1$p.value), 100 * mean(a$n_dependent >= 11), 100 * mean(b$n_dependent >= 11), fp(f2$p.value)))
  par(mar = c(4.4, 6, 3.4, 4)); n <- nrow(PL); plot(PL$diff, seq_len(n), pch = 21, bg = ifelse(PL$p < 0.05, SC, "white"), col = INK2, cex = 1.4, yaxt = "n", bty = "n", xlab = "median gene effect: selected minus other TFs", ylab = "", cex.axis = 0.8, xlim = range(c(0, PL$diff)) + c(-0.01, 0.01)); abline(v = 0, lty = 2, col = INK); segments(0, seq_len(n), PL$diff, seq_len(n), col = GRID)
  points(PL$diff, seq_len(n), pch = 21, bg = ifelse(PL$p < 0.05, SC, "white"), col = INK2, cex = 1.4); axis(2, at = seq_len(n), labels = PL$line, las = 1, tick = FALSE, cex.axis = 0.62); text(par("usr")[2], seq_len(n), sprintf("p %s", fp(PL$p)), adj = 0, xpd = NA, cex = 0.55)
  ttl("B  the same in each mesothelioma line", sprintf("selected lower in %d of %d lines; filled = Wilcoxon p < 0.05", sum(PL$diff < 0), n))
  par(mar = c(4.4, 5, 3.4, 3)); n <- nrow(a); cols <- colorRampPalette(c("#f7f6f2", "#f0a58f", "#a8380b"))(22)[a$n_dependent + 1]; bp <- barplot(rev(a$meso_median), horiz = TRUE, col = rev(cols), border = "grey50", lwd = 0.3, las = 1, names.arg = rev(a$TF), cex.names = 0.55, xlab = "median gene effect, 21 mesothelioma lines", cex.axis = 0.8, xlim = c(min(a$meso_median) - 0.05, max(a$meso_median) + 0.25)); abline(v = c(0, -0.5, -1), lty = c(1, 3, 2), col = c(INK, MUTED, MUTED))
  points(rev(a$other_median), bp, pch = "|", cex = 0.8, col = "#2a78d6"); text(pmax(rev(a$meso_median), 0) + 0.03, bp, ifelse(rev(a$n_dependent) > 0, sprintf("%d/21", rev(a$n_dependent)), ""), adj = 0, cex = 0.5, xpd = NA); legend("bottomright", c("bar colour = lines dependent", "| = median of all other DepMap lines"), bty = "n", cex = 0.6, text.col = c(INK2, "#2a78d6"))
  ttl("C  the 68 selected TFs", "sorted by the median effect; n/21 = mesothelioma lines with dependency probability > 0.5")
  par(mar = c(4.4, 4.8, 3.4, 1)); plot(b$expr_meso, b$meso_median, pch = 16, cex = 0.6, col = adjustcolor(BC, 0.6), bty = "n", las = 1, xlab = "expression in mesothelioma lines (CCLE, median log2 TPM + 1)", ylab = "median gene effect, mesothelioma lines", cex.axis = 0.8, ylim = range(T$meso_median), xlim = range(T$expr_meso, na.rm = TRUE)); points(a$expr_meso, a$meso_median, pch = 21, bg = SC, col = INK2, cex = 1.1)
  abline(h = 0, col = GRID); for (d in list(list(b, BC), list(a, SC))) { ok <- !is.na(d[[1]]$expr_meso); lines(lowess(d[[1]]$expr_meso[ok], d[[1]]$meso_median[ok], f = 0.8), col = d[[2]], lwd = 2) }; lab <- a[a$meso_median < -0.3, ]; text(lab$expr_meso, lab$meso_median, lab$TF, pos = 2, cex = 0.55, xpd = NA)
  ttl("D  adjusted for expression", sprintf("'selected' given expression: %+.3f, p %s; matched draws p %s", m1["selectedTRUE", 1], fp(m1["selectedTRUE", 4]), fp(p_match)))
  par(mar = c(4.4, 4.8, 3.4, 1)); boxplot(list(`68 selected` = a$selectivity, `other chromVAR TFs` = b$selectivity), col = c(adjustcolor(SC, 0.6), "#d5d4cf"), border = INK2, outline = FALSE, las = 1, ylab = "mesothelioma minus other lineages (median gene effect)", cex.axis = 0.8, ylim = range(T$selectivity)); abline(h = 0, lty = 2, col = INK)
  points(jitter(rep(1, nrow(a)), 6), a$selectivity, pch = 16, cex = 0.6, col = INK2); lab <- a[order(a$selectivity)[1:6], ]; text(1.12, lab$selectivity, lab$TF, adj = 0, cex = 0.55, xpd = NA); lb <- b[order(b$selectivity)[1:5], ]; text(2.1, lb$selectivity, lb$TF, adj = 0, cex = 0.5, col = MUTED, xpd = NA); points(rep(2, 5), lb$selectivity, pch = 16, cex = 0.5, col = MUTED)
  ttl("E  is the requirement specific to mesothelioma?", sprintf("< 0 = more required in mesothelioma than elsewhere; Wilcoxon p %s", fp(w2$p.value)))
  mtext("DepMap CRISPR viability in 21 mesothelioma lines: the 68 tumour-selected TFs vs the other TFs with chromVAR activity", outer = TRUE, side = 3, adj = 0, line = 2, font = 2, cex = 1.05); mtext("DepMap Public 24Q4, Chronos gene effect (0 = no effect, -1 = like a common essential gene)", outer = TRUE, side = 3, adj = 0, line = 0.8, cex = 0.66, col = INK2)
})
